const $ = (s) => document.querySelector(s);
const app = $('#app');
let token = localStorage.getItem('token');
let me = JSON.parse(localStorage.getItem('me') || 'null');
let state = { page:'dashboard', users:[], clients:[], events:[], rates:[], documents:[], notes:[], entries:[], reports:[], dashboard:null, settings:{} };
const pages = [
  ['OPERATIVA','dashboard','Dashboard'],['OPERATIVA','calendario','Calendario eventos'],['OPERATIVA','control','Control diario'],['OPERATIVA','gps','GPS Live'],['OPERATIVA','vista-operario','Vista operario'],
  ['GESTIÓN','clientes','Clientes'],['GESTIÓN','eventos','Eventos'],['GESTIÓN','realizados','Eventos realizados'],['GESTIÓN','operarios','Operarios'],['GESTIÓN','usuarios','Usuarios admin'],['GESTIÓN','tarifas','Tarifas'],['GESTIÓN','documentacion','Documentación'],
  ['ADMINISTRACIÓN','albaranes','Albaranes evento'],['ADMINISTRACIÓN','finanzas','Finanzas Pro'],['ADMINISTRACIÓN','informes','Informes PDF'],['ADMINISTRACIÓN','passwords','Contraseñas'],
  ['SISTEMA','ajustes','Ajustes ERP']
];
async function api(path, opts={}){ const res=await fetch(path,{...opts,headers:{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`}:{}) ,...(opts.headers||{})}}); const data=await res.json().catch(()=>({})); if(!res.ok) throw new Error(data.error||'Error de servidor'); return data; }
function esc(v){return String(v??'').replace(/[&<>"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]))}
function toast(msg){ const d=document.createElement('div'); d.className='toast'; d.textContent=msg; document.body.appendChild(d); setTimeout(()=>d.remove(),2600); }
function roleLabel(r){return {super_admin:'Super Admin',admin:'Admin',team_lead:'Jefe equipo',operator:'Operario',client:'Cliente'}[r]||r}
function statusLabel(s){return {planned:'Planificado',confirmed:'Confirmado',done:'Realizado',realizado:'Realizado',cancelled:'Cancelado'}[s]||s}
function money(n){return new Intl.NumberFormat('es-ES',{style:'currency',currency:'EUR'}).format(Number(n||0))}
function dateES(v){return v?new Date(v+'T00:00:00').toLocaleDateString('es-ES'):''}
async function boot(){ if(!token) return renderLogin(); await loadBase(); renderShell(); }
function renderLogin(){ app.innerHTML=`<main class="login"><section class="login-card"><div class="brand big"><img src="/logo.png" onerror="this.style.display='none'"><div><h1>Marfan Crew 2.0.4</h1><p>Enterprise · Datos V62.49 integrados</p></div></div><form id="loginForm"><div class="field"><label>Email o teléfono</label><input name="login" value="admin@marfan.local" required></div><div class="field"><label>Contraseña</label><input name="password" type="password" value="Admin1234!" required></div><button class="blue full">Entrar</button><p class="muted small">Usuario inicial: admin@marfan.local / Admin1234!</p></form></section></main>`; $('#loginForm').onsubmit=async e=>{e.preventDefault(); try{ const r=await api('/api/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))}); token=r.token; me=r.user; localStorage.setItem('token',token); localStorage.setItem('me',JSON.stringify(me)); await boot(); }catch(err){toast(err.message)}}; }
async function loadBase(){ try{ [state.dashboard,state.users,state.clients,state.events,state.rates,state.documents,state.notes,state.entries,state.reports,state.settings]=await Promise.all([api('/api/dashboard'),api('/api/users'),api('/api/clients'),api('/api/events'),api('/api/rates').catch(()=>[]),api('/api/documents').catch(()=>[]),api('/api/delivery-notes').catch(()=>[]),api('/api/time/entries').catch(()=>[]),api('/api/reports/summary').catch(()=>[]),api('/api/settings').catch(()=>({}))]); }catch(e){ localStorage.clear(); token=null; me=null; renderLogin(); } }
function renderShell(){ const groups={}; pages.forEach(p=>(groups[p[0]]??=[]).push(p)); app.innerHTML=`<div class="shell"><aside class="side"><div class="brand"><img src="/logo.png" onerror="this.remove()"><div><h1>MARFAN CREW</h1><p>App 2.0.4</p></div></div><div class="nav">${Object.entries(groups).map(([g,items])=>`<div class="navgroup"><span>${g}</span>${items.map(p=>`<button data-page="${p[1]}" class="${state.page===p[1]?'active':''}">${p[2]}</button>`).join('')}</div>`).join('')}</div><div class="userbox"><p>${esc(me?.name||'')}<br><b>${roleLabel(me?.role)}</b></p><button class="secondary full" id="logout">Salir</button></div></aside><main class="main" id="main"></main></div>`; document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page; renderShell();}); $('#logout').onclick=()=>{localStorage.clear();token=null;renderLogin()}; renderPage(); }
function header(title,sub,actions=''){return `<div class="top"><div><h2>${title}</h2><p>${sub}</p></div><div class="actions">${actions}</div></div>`}
function table(head,rows){return `<div class="tablewrap"><table class="table"><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c??''}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${head.length}">Sin datos todavía.</td></tr>`}</tbody></table></div>`}
function renderPage(){ ({dashboard,calendario,control,gps,'vista-operario':vistaOperario,clientes,eventos,realizados,operarios,usuarios,tarifas,documentacion,albaranes,finanzas,informes,passwords,ajustes}[state.page]||dashboard)(); }
function dashboard(){ const d=state.dashboard||{}; $('#main').innerHTML=header('Dashboard','Visión general de personal, eventos y facturación.')+`<div class="grid kpis"><div class="card kpi"><b>${d.users||0}</b><span>Usuarios activos</span></div><div class="card kpi"><b>${d.operators||0}</b><span>Operarios</span></div><div class="card kpi"><b>${d.eventsToday||0}</b><span>Eventos hoy</span></div><div class="card kpi"><b>${money(d.monthRevenue)}</b><span>Presupuesto mes</span></div><div class="card kpi"><b>${d.activeWorkers||0}</b><span>Fichajes abiertos</span></div><div class="card kpi"><b>${d.clients||0}</b><span>Clientes</span></div></div><section class="card panel"><h3>Próximos eventos</h3>${table(['Fecha','Hora','Evento','Cliente','Personal','Estado'],(d.nextEvents||[]).map(e=>[dateES(e.date),`${e.start_time||''}-${e.end_time||''}`,esc(e.title),esc(e.client_name||'-'),e.assigned_count||0,`<span class="pill">${statusLabel(e.status)}</span>`]))}</section>`; }
function calendario(){ const byDate={}; state.events.forEach(e=>{(byDate[e.date]??=[]).push(e)}); const days=Object.keys(byDate).sort(); $('#main').innerHTML=header('Calendario eventos','Vista cronológica tipo Google Calendar simplificada.','<button class="blue" id="newEvent">Crear evento</button>')+`<section class="calendar">${days.length?days.map(d=>`<div class="day card"><h3>${dateES(d)}</h3>${byDate[d].map(e=>`<div class="event"><b>${esc(e.start_time)} · ${esc(e.title)}</b><p>${esc(e.client_name||'Sin cliente')} · ${esc(e.location||'')}</p><span class="pill">${statusLabel(e.status)}</span></div>`).join('')}</div>`).join(''):'<div class="card">No hay eventos.</div>'}</section>`; $('#newEvent').onclick=()=>eventModal(); }
function control(){ const today=new Date().toISOString().slice(0,10); const ev=state.events.filter(e=>e.date===today); $('#main').innerHTML=header('Control diario','Eventos de hoy, personal asignado y fichajes abiertos.')+`<div class="grid"><section class="card"><h3>Eventos hoy</h3>${table(['Hora','Evento','Cliente','Estado'],ev.map(e=>[`${e.start_time}-${e.end_time}`,esc(e.title),esc(e.client_name||''),statusLabel(e.status)]))}</section><section class="card"><h3>Fichajes recientes</h3>${table(['Operario','Evento','Entrada','Salida'],state.entries.slice(0,10).map(t=>[esc(t.user_name),esc(t.event_title),esc(t.check_in),esc(t.check_out||'Abierto')]))}</section></div>`; }
function gps(){ $('#main').innerHTML=header('GPS Live','Últimas posiciones registradas en fichajes.')+`<section class="card">${table(['Operario','Evento','Entrada GPS','Salida GPS'],state.entries.filter(t=>t.check_in_lat||t.check_out_lat).map(t=>[esc(t.user_name),esc(t.event_title),`${t.check_in_lat||''}, ${t.check_in_lng||''}`,`${t.check_out_lat||''}, ${t.check_out_lng||''}`]))}<p class="muted">El mapa visual se deja preparado para fase 2 con Google Maps/Mapbox.</p></section>`; }
function vistaOperario(){ const my=state.events.slice(0,20); $('#main').innerHTML=header('Vista operario','Pantalla móvil para fichar entrada/salida y ver eventos asignados.')+`<section class="card">${table(['Fecha','Hora','Evento','Acción'],my.map(e=>[dateES(e.date),`${e.start_time}-${e.end_time}`,esc(e.title),`<button class="secondary" onclick="checkIn(${e.id})">Fichar entrada</button>`]))}</section>`; }
window.checkIn=async id=>{ const send=async(pos={})=>{try{await api('/api/time/check-in',{method:'POST',body:JSON.stringify({event_id:id,lat:pos.lat,lng:pos.lng})}); await loadBase(); renderShell(); toast('Entrada registrada')}catch(e){toast(e.message)}}; if(navigator.geolocation) navigator.geolocation.getCurrentPosition(p=>send({lat:p.coords.latitude,lng:p.coords.longitude}),()=>send()); else send(); }
function clientes(){ $('#main').innerHTML=header('Clientes','Base de datos de clientes con fiscal, contacto y notas.','<button class="blue" id="newClient">Crear cliente</button>')+`<section class="card">${table(['Cliente','Razón social','CIF','Contacto','Email','Teléfono','Provincia'],state.clients.map(c=>[esc(c.name),esc(c.legal_name),esc(c.cif),esc(c.contact_name),esc(c.email),esc(c.phone),esc(c.province)]))}</section>`; $('#newClient').onclick=()=>clientModal(); }
function eventos(){ $('#main').innerHTML=header('Eventos','Creación de eventos con cliente, localización, producción y asignación de equipo.','<button class="blue" id="newEvent">Crear evento</button>')+`<section class="card">${table(['Fecha','Hora','Evento','Cliente','Localización','Personal','Presupuesto'],state.events.map(e=>[dateES(e.date),`${e.start_time}-${e.end_time}`,esc(e.title),esc(e.client_name||'-'),esc(e.location),e.assigned_count,money(e.budget)]))}</section>`; $('#newEvent').onclick=()=>eventModal(); }
function realizados(){ const rows=state.events.filter(e=>['done','realizado'].includes(e.status)); $('#main').innerHTML=header('Eventos realizados','Histórico operativo para informes y albaranes.')+`<section class="card">${table(['Fecha','Evento','Cliente','Importe'],rows.map(e=>[dateES(e.date),esc(e.title),esc(e.client_name),money(e.budget)]))}</section>`; }
function operarios(){ const rows=state.users.filter(u=>['operator','team_lead'].includes(u.role)); $('#main').innerHTML=header('Operarios','Equipo operativo importado desde V62.49: login por teléfono/email, DNI, Seguridad Social, IBAN y documentación.','<button class="blue" id="newUser">Crear operario</button>')+`<section class="card"><p class="muted">Contraseña inicial de operarios importados: <b>Marfan1234*</b>. Pueden entrar con teléfono o email.</p>${table(['Nombre','Teléfono','Email','DNI','Nº SS','IBAN','Rol','Tarifa','Estado','Acciones'],rows.map(u=>[esc(u.name),esc(u.phone),esc(u.email),esc(u.dni),esc(u.social_security_number),esc(u.iban||u.bank_iban),roleLabel(u.role),money(u.hourly_rate),u.active?'Activo':'Inactivo',`<button class="secondary" onclick="editUser(${u.id})">Editar</button> <button class="secondary" onclick="resetPass(${u.id})">Reset</button>`]))}</section>`; $('#newUser').onclick=()=>userModal({role:'operator',password:'Marfan1234*'}); }
function usuarios(){ $('#main').innerHTML=header('Usuarios admin','Crea administradores, jefes de equipo, operarios y clientes. Los operarios importados entran con teléfono/email.','<button class="blue" id="newUser">Crear usuario</button>')+`<section class="card">${table(['Nombre','Contacto','Rol','Tarifa','Estado','Acciones'],state.users.map(u=>[esc(u.name),`${esc(u.email||'')}<br>${esc(u.phone||'')}`,`<span class="pill">${roleLabel(u.role)}</span>`,money(u.hourly_rate),u.active?'Activo':'Inactivo',`<button class="secondary" onclick="editUser(${u.id})">Editar</button> <button class="secondary" onclick="resetPass(${u.id})">Reset</button>`]))}</section>`; $('#newUser').onclick=()=>userModal(); }
function tarifas(){ $('#main').innerHTML=header('Tarifas','Cargos, tarifa diurna y nocturna.','<button class="blue" id="newRate">Crear tarifa</button>')+`<section class="card">${table(['Cargo','Diurna','Nocturna','Estado'],state.rates.map(r=>[esc(r.role),money(r.day_rate),money(r.night_rate),r.active?'Activa':'Inactiva']))}</section>`; $('#newRate').onclick=()=>rateModal(); }
function documentacion(){ $('#main').innerHTML=header('Documentación','Control documental de operarios, clientes y empresa.','<button class="blue" id="newDoc">Crear documento</button>')+`<section class="card">${table(['Título','Tipo','Propietario','Caducidad','Notas'],state.documents.map(d=>[esc(d.title),esc(d.type),esc(d.owner_type),esc(d.expiry_date),esc(d.notes)]))}</section>`; $('#newDoc').onclick=()=>docModal(); }
function albaranes(){ $('#main').innerHTML=header('Albaranes evento','Albaranes generados desde eventos, con IVA y firma preparada.')+`<section class="card">${table(['Número','Fecha','Cliente','Base','Total IVA','Firmado'],state.notes.map(n=>[esc(n.number),dateES(n.event_date),esc(n.client_name),money(n.grand_total),money(n.grand_total_vat),n.client_signed?'Sí':'No']))}</section>`; }
function finanzas(){ const total=state.events.reduce((s,e)=>s+Number(e.budget||0),0); const cost=state.events.reduce((s,e)=>s+Number(e.external_cost||0)+Number(e.transport_cost||0)+Number(e.other_cost||0),0); $('#main').innerHTML=header('Finanzas Pro','Facturación, costes y beneficio estimado.')+`<div class="grid kpis"><div class="card kpi"><b>${money(total)}</b><span>Facturación prevista</span></div><div class="card kpi"><b>${money(cost)}</b><span>Costes</span></div><div class="card kpi"><b>${money(total-cost)}</b><span>Beneficio estimado</span></div></div><section class="card"><h3>Resumen mensual</h3>${table(['Mes','Eventos','Facturación','Coste','Beneficio'],state.reports.map(r=>[esc(r.month),r.events,money(r.amount),money(r.cost),money(r.profit)]))}</section>`; }
function informes(){ $('#main').innerHTML=header('Informes PDF','Informes imprimibles desde navegador.')+`<div class="grid"><div class="card"><h3>Eventos semanales</h3><p class="muted">Listado de eventos con cliente y personal.</p><button onclick="printPage()">Imprimir informe</button></div><div class="card"><h3>Historial horas operarios</h3><p class="muted">Resumen con fichajes y horas.</p><button onclick="printPage()">Imprimir informe</button></div><div class="card"><h3>Historial cliente</h3><p class="muted">Eventos, importes e IVA.</p><button onclick="printPage()">Imprimir informe</button></div></div>`; }
window.printPage=()=>window.print();
function passwords(){ $('#main').innerHTML=header('Contraseñas','Reset rápido de contraseñas de usuarios.')+`<section class="card">${table(['Usuario','Rol','Acción'],state.users.map(u=>[esc(u.name),roleLabel(u.role),`<button class="secondary" onclick="resetPass(${u.id})">Reset contraseña</button>`]))}</section>`; }
function ajustes(){ $('#main').innerHTML=header('Ajustes ERP','IVA, dietas, kilometraje, empresa y configuración base.')+`<section class="card"><form id="settingsForm" class="formgrid">${['company_name','vat_percent','km_rate','diet_amount','night_start','night_end','hq_address'].map(k=>`<label>${k}<input name="${k}" value="${esc(state.settings[k]||'')}"></label>`).join('')}<button class="blue">Guardar ajustes</button></form></section>`; $('#settingsForm').onsubmit=async e=>{e.preventDefault(); try{await api('/api/settings',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))}); await loadBase(); toast('Ajustes guardados')}catch(err){toast(err.message)}}; }
function modal(html){ document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="modal"><div class="modalcard">${html}</div></div>`); }
window.closeModal=()=>$('#modal')?.remove();
window.editUser=id=>userModal(state.users.find(x=>x.id===id));
window.resetPass=async id=>{ const password=prompt('Nueva contraseña mínimo 8 caracteres'); if(password) try{await api(`/api/users/${id}/reset-password`,{method:'POST',body:JSON.stringify({password})}); toast('Contraseña actualizada')}catch(e){toast(e.message)} };
function userModal(u={}){ modal(`<h3>${u.id?'Editar usuario':'Crear usuario'}</h3><form id="f" class="formgrid"><input name="name" placeholder="Nombre completo" value="${esc(u.name||'')}" required><input name="first_name" placeholder="Nombre" value="${esc(u.first_name||'')}"><input name="last_name" placeholder="Apellidos" value="${esc(u.last_name||'')}"><input name="nickname" placeholder="Alias" value="${esc(u.nickname||'')}"><input name="email" placeholder="Email / login" value="${esc(u.email||'')}"><input name="phone" placeholder="Teléfono / login" value="${esc(u.phone||'')}"><select name="role"><option value="admin">Admin</option><option value="team_lead">Jefe equipo</option><option value="operator">Operario</option><option value="client">Cliente</option><option value="super_admin">Super Admin</option></select><input name="hourly_rate" type="number" step="0.01" placeholder="Tarifa/hora" value="${u.hourly_rate||0}"><input name="position" placeholder="Cargo" value="${esc(u.position||'')}"><input name="operator_role_name" placeholder="Rol operativo" value="${esc(u.operator_role_name||'')}"><input name="dni" placeholder="DNI/NIE" value="${esc(u.dni||'')}"><input name="social_security_number" placeholder="Nº Seguridad Social" value="${esc(u.social_security_number||'')}"><input name="iban" placeholder="IBAN" value="${esc(u.iban||u.bank_iban||'')}"><input name="bank_name" placeholder="Banco" value="${esc(u.bank_name||'')}"><input name="full_address" placeholder="Dirección completa" value="${esc(u.full_address||u.address||'')}"><input name="shirt_size" placeholder="Talla camiseta" value="${esc(u.shirt_size||'')}"><input name="pants_size" placeholder="Talla pantalón" value="${esc(u.pants_size||'')}"><input name="shoe_size" placeholder="Talla calzado" value="${esc(u.shoe_size||'')}"><input name="emergency_contact_name" placeholder="Contacto emergencia" value="${esc(u.emergency_contact_name||'')}"><input name="emergency_contact_phone" placeholder="Teléfono emergencia" value="${esc(u.emergency_contact_phone||u.emergency_phone||'')}"><textarea name="notes" placeholder="Notas">${esc(u.notes||'')}</textarea>${u.id?'':'<input name="password" placeholder="Contraseña inicial" value="Marfan1234*" required>'}<select name="active"><option value="1">Activo</option><option value="0">Inactivo</option></select><label class="check"><input name="has_prl" type="checkbox" ${u.has_prl?'checked':''}> PRL entregado</label><label class="check"><input name="epis_delivered" type="checkbox" ${u.epis_delivered?'checked':''}> EPIs entregados</label><button class="blue">Guardar</button><button type="button" class="secondary" onclick="closeModal()">Cancelar</button></form>`); if(u.role) $('[name=role]').value=u.role; if(u.active===0) $('[name=active]').value='0'; $('#f').onsubmit=async e=>{e.preventDefault(); let body=Object.fromEntries(new FormData(e.target)); body.active=body.active==='1'; body.hourly_rate=Number(body.hourly_rate||0); body.has_prl=e.target.has_prl?.checked?1:0; body.epis_delivered=e.target.epis_delivered?.checked?1:0; body.bank_iban=body.iban; body.address=body.full_address; try{await api(u.id?`/api/users/${u.id}`:'/api/users',{method:u.id?'PUT':'POST',body:JSON.stringify(body)}); closeModal(); await loadBase(); renderShell(); toast('Usuario guardado')}catch(err){toast(err.message)}}; }
function clientModal(){ modal(`<h3>Crear cliente</h3><form id="f" class="formgrid"><input name="name" placeholder="Nombre cliente" required><input name="legal_name" placeholder="Razón social"><input name="cif" placeholder="CIF/NIF"><input name="contact_name" placeholder="Contacto"><input name="email" placeholder="Email"><input name="phone" placeholder="Teléfono"><input name="address" placeholder="Dirección"><input name="province" placeholder="Provincia"><textarea name="notes" placeholder="Notas"></textarea><button class="blue">Guardar</button><button type="button" class="secondary" onclick="closeModal()">Cancelar</button></form>`); $('#f').onsubmit=async e=>{e.preventDefault(); try{await api('/api/clients',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))}); closeModal(); await loadBase(); renderShell(); toast('Cliente creado')}catch(err){toast(err.message)}}; }
function eventModal(){ const ops=state.users.filter(u=>['operator','team_lead'].includes(u.role)); modal(`<h3>Crear evento</h3><form id="f" class="formgrid"><input name="title" placeholder="Nombre evento" required><input name="event_code" placeholder="Código evento"><select name="client_id"><option value="">Sin cliente</option>${state.clients.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><input name="location" placeholder="Localización"><input name="address" placeholder="Dirección"><input name="google_maps_link" placeholder="Google Maps"><input name="date" type="date" required><input name="start_time" type="time" required><input name="end_time" type="time" required><input name="load_in_time" type="time" placeholder="Carga"><input name="load_out_time" type="time"><input name="service_type" placeholder="Tipo servicio"><input name="budget" type="number" step="0.01" placeholder="Presupuesto"><input name="external_cost" type="number" step="0.01" placeholder="Coste externo"><input name="transport_cost" type="number" step="0.01" placeholder="Transporte"><input name="other_cost" type="number" step="0.01" placeholder="Otros costes"><select name="status"><option value="planned">Planificado</option><option value="confirmed">Confirmado</option><option value="done">Realizado</option><option value="cancelled">Cancelado</option></select><textarea name="material_notes" placeholder="Material"></textarea><textarea name="crew_notes" placeholder="Personal"></textarea><textarea name="production_notes" placeholder="Producción"></textarea><div class="fullrow"><b>Equipo</b><br>${ops.map(o=>`<label class="check"><input type="checkbox" name="assignments" value="${o.id}">${esc(o.name)}</label>`).join('')}</div><button class="blue">Guardar</button><button type="button" class="secondary" onclick="closeModal()">Cancelar</button></form>`); $('#f').onsubmit=async e=>{e.preventDefault(); const fd=new FormData(e.target); const body=Object.fromEntries(fd); body.assignments=fd.getAll('assignments').map(Number); ['budget','external_cost','transport_cost','other_cost'].forEach(k=>body[k]=Number(body[k]||0)); try{await api('/api/events',{method:'POST',body:JSON.stringify(body)}); closeModal(); await loadBase(); renderShell(); toast('Evento creado')}catch(err){toast(err.message)}}; }
function rateModal(){ modal(`<h3>Crear tarifa</h3><form id="f" class="formgrid"><input name="role" placeholder="Cargo" required><input name="day_rate" type="number" step="0.01" placeholder="Tarifa diurna"><input name="night_rate" type="number" step="0.01" placeholder="Tarifa nocturna"><button class="blue">Guardar</button><button type="button" class="secondary" onclick="closeModal()">Cancelar</button></form>`); $('#f').onsubmit=async e=>{e.preventDefault(); const b=Object.fromEntries(new FormData(e.target)); b.day_rate=Number(b.day_rate||0); b.night_rate=Number(b.night_rate||0); try{await api('/api/rates',{method:'POST',body:JSON.stringify(b)}); closeModal(); await loadBase(); renderShell(); toast('Tarifa creada')}catch(err){toast(err.message)}}; }
function docModal(){ modal(`<h3>Crear documento</h3><form id="f" class="formgrid"><input name="title" placeholder="Título" required><input name="type" placeholder="Tipo"><input name="owner_type" placeholder="Operario / Cliente / Empresa"><input name="expiry_date" type="date"><textarea name="notes" placeholder="Notas"></textarea><button class="blue">Guardar</button><button type="button" class="secondary" onclick="closeModal()">Cancelar</button></form>`); $('#f').onsubmit=async e=>{e.preventDefault(); try{await api('/api/documents',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))}); closeModal(); await loadBase(); renderShell(); toast('Documento creado')}catch(err){toast(err.message)}}; }

// ---------- V2.0.4 UI OPERATIVA REAL ----------
async function loadBase(){ try{ [state.dashboard,state.users,state.clients,state.events,state.rates,state.documents,state.notes,state.entries,state.reports,state.settings,state.gps,state.daily,state.passwordVault]=await Promise.all([api('/api/dashboard'),api('/api/users').catch(()=>[]),api('/api/clients').catch(()=>[]),api('/api/events').catch(()=>[]),api('/api/rates').catch(()=>[]),api('/api/documents').catch(()=>[]),api('/api/event-delivery-notes').catch(()=>api('/api/delivery-notes').catch(()=>[])),api('/api/time/entries').catch(()=>[]),api('/api/reports/summary').catch(()=>[]),api('/api/settings').catch(()=>({})),api('/api/gps/live').catch(()=>[]),api('/api/admin/daily-control').catch(()=>null),api('/api/passwords').catch(()=>[])]); }catch(e){ console.error(e); localStorage.clear(); token=null; me=null; renderLogin(); } }
