function albaranes(){ $('#main').innerHTML=header('Albaranes evento','Generación de albarán por evento con horas, firma, IVA y descarga PDF A4 profesional.','<button class="blue" onclick="deliveryModal()">Generar albarán</button>')+`<section class="card">${table(['Número','Fecha','Cliente','Horas normales','Horas nocturnas','Total','IVA incluido','Firma','PDF A4'],(state.notes||[]).map(n=>[esc(n.number),dateES(n.event_date),esc(n.client_name),Number(n.normal_hours||0).toFixed(2),Number(n.night_hours||0).toFixed(2),money(n.grand_total),money(n.grand_total_vat),n.client_signed?'Firmado':'Pendiente',`<button class="blue smallbtn" onclick="downloadDeliveryPDF(${n.id})">Descargar PDF A4</button>`]))}</section>`; }
window.downloadDeliveryPDF=async(id)=>{ try{ const res=await fetch(`/api/event-delivery-notes/${id}/pdf`,{headers:{Authorization:`Bearer ${token}`}}); if(!res.ok){ const err=await res.json().catch(()=>({error:'Error descargando PDF'})); throw new Error(err.error||'Error descargando PDF'); } const blob=await res.blob(); const url=URL.createObjectURL(blob); const a=document.createElement('a'); a.href=url; a.download=`albaran-${id}.pdf`; document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(url); }catch(e){ toast(e.message); } }
