renderShell = function(){ const groups={}; visiblePages().forEach(p=>(groups[p[0]]??=[]).push(p)); app.innerHTML=`<div class="shell"><aside class="side"><div class="brand"><img src="/logo.png" onerror="this.remove()"><div><h1>MARFAN CREW</h1><p>App 2.0.5</p></div></div><div class="nav">${Object.entries(groups).map(([g,items])=>`<div class="navgroup"><span>${g}</span>${items.map(p=>`<button data-page="${p[1]}" class="${state.page===p[1]?'active':''}">${p[2]}</button>`).join('')}</div>`).join('')}</div><div class="userbox"><p>${esc(me?.name||'')}<br><b>${roleLabel(me?.role)}</b></p><button class="secondary full" id="logout">Salir</button></div></aside><main class="main" id="main"></main></div>`; document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page; renderShell();}); $('#logout').onclick=()=>{localStorage.clear();token=null;renderLogin()}; renderPage(); }
