calendario = function(){ const months={}; state.events.forEach(e=>{ const k=(e.date||'Sin fecha').slice(0,7); (months[k]??=[]).push(e); }); $('#main').innerHTML=header('Calendario Pro','Vista mensual/lista con colores por estado y edición rápida.','<button class="blue" id="newEvent">Crear evento</button>')+`<section class="calendar">${Object.keys(months).sort().map(m=>`<div class="day card"><h3>${m}</h3>${months[m].sort((a,b)=>(a.date+a.start_time).localeCompare(b.date+b.start_time)).map(e=>`<div class="event status-${esc(e.status)}" onclick="eventModal(${e.id})"><b>${dateES(e.date)} · ${esc(e.start_time)} · ${esc(e.title)}</b><p>${esc(e.client_name||'Sin cliente')} · ${esc(e.location||'')}</p><span class="pill">${statusLabel(e.status)}</span></div>`).join('')}</div>`).join('')||'<div class="card">No hay eventos.</div>'}</section>`; $('#newEvent').onclick=()=>eventModal(); }
vistaOperario = function(){ const my=state.events; $('#main').innerHTML=header('Vista operario','Solo aparecen tus eventos asignados. Fichaje con GPS y geocerca.')+`<div class="grid"><section class="card"><h3>Mis eventos asignados</h3>${table(['Fecha','Hora','Evento','Cliente','Lugar','Acciones'],my.slice(0,80).map(e=>[dateES(e.date),`${e.start_time||''}-${e.end_time||''}`,esc(e.title),esc(e.client_name||''),esc(e.location||''),`<button class="blue" onclick="checkIn(${e.id})">Entrada</button> <button class="secondary" onclick="checkOut(${e.id})">Salida</button>`]))}</section><section class="card"><h3>Mis fichajes</h3><div id="myEntries">Cargando...</div></section></div>`; api('/api/my-time-entries').then(rows=>{$('#myEntries').innerHTML=table(['Evento','Entrada','Salida','Descanso','Corrección'],rows.map(r=>[esc(r.event_title),esc(r.check_in),esc(r.check_out||'Abierto'),r.break_minutes||0,r.admin_corrected?'Sí':'No']))}).catch(()=>{}); }
window.checkIn=async id=>{ const send=async(pos={})=>{try{await api('/api/time-log',{method:'POST',body:JSON.stringify({event_id:id,action:'check_in',lat:pos.lat,lng:pos.lng})}); await loadBase(); renderShell(); toast('Entrada registrada con GPS')}catch(e){toast(e.message)}}; if(navigator.geolocation) navigator.geolocation.getCurrentPosition(p=>send({lat:p.coords.latitude,lng:p.coords.longitude}),()=>{toast('GPS no concedido. Se intentará fichar sin coordenadas.'); send();},{enableHighAccuracy:true,timeout:10000}); else send(); }
window.checkOut=async id=>{ const break_minutes=Number(prompt('Minutos de descanso/pausa', '0')||0); const send=async(pos={})=>{try{await api('/api/time-log',{method:'POST',body:JSON.stringify({event_id:id,action:'check_out',lat:pos.lat,lng:pos.lng,break_minutes})}); await loadBase(); renderShell(); toast('Salida registrada')}catch(e){toast(e.message)}}; if(navigator.geolocation) navigator.geolocation.getCurrentPosition(p=>send({lat:p.coords.latitude,lng:p.coords.longitude}),()=>send(),{enableHighAccuracy:true,timeout:10000}); else send(); }
albaranes = function(){ $('#main').innerHTML=header('Albaranes A4 Pro','Albarán por evento con líneas por operario, firma manuscrita y bloqueo tras firma.','<button class="blue" onclick="deliveryModal()">Generar albarán</button>')+`<section class="card">${table(['Número','Fecha','Cliente','Horas normales','Horas nocturnas','Total','IVA incluido','Estado','Acciones'],(state.notes||[]).map(n=>[esc(n.number),dateES(n.event_date),esc(n.client_name),Number(n.normal_hours||0).toFixed(2),Number(n.night_hours||0).toFixed(2),money(n.grand_total),money(n.grand_total_vat),n.locked?'Firmado/bloqueado':'Pendiente',`<button class="blue smallbtn" onclick="downloadDeliveryPDF(${n.id})">PDF A4</button> ${n.locked?'':`<button class="secondary smallbtn" onclick="signDelivery(${n.id})">Firmar</button>`}`]))}</section>`; }
window.signDelivery=(id)=>{ modal(`<h3>Firmar albarán</h3><form id="f" class="formgrid"><input name="signature_name" placeholder="Nombre cliente" required><input name="signature_dni" placeholder="DNI/NIF"><canvas id="sig" width="480" height="160" style="border:1px solid #ddd;border-radius:12px;background:#fff;touch-action:none"></canvas><button type="button" class="secondary" id="clearSig">Limpiar firma</button><button class="blue">Firmar y bloquear</button><button type="button" class="secondary" onclick="closeModal()">Cancelar</button></form>`); const c=$('#sig'), ctx=c.getContext('2d'); ctx.lineWidth=2; let drawing=false; const pos=e=>{const r=c.getBoundingClientRect(); const p=e.touches?e.touches[0]:e; return {x:p.clientX-r.left,y:p.clientY-r.top};}; const down=e=>{drawing=true; const p=pos(e); ctx.beginPath(); ctx.moveTo(p.x,p.y); e.preventDefault();}; const move=e=>{if(!drawing)return; const p=pos(e); ctx.lineTo(p.x,p.y); ctx.stroke(); e.preventDefault();}; const up=()=>drawing=false; ['mousedown','touchstart'].forEach(ev=>c.addEventListener(ev,down)); ['mousemove','touchmove'].forEach(ev=>c.addEventListener(ev,move)); ['mouseup','mouseleave','touchend'].forEach(ev=>c.addEventListener(ev,up)); $('#clearSig').onclick=()=>ctx.clearRect(0,0,c.width,c.height); $('#f').onsubmit=async e=>{e.preventDefault(); const b=Object.fromEntries(new FormData(e.target)); b.signature_data_url=c.toDataURL('image/png'); try{await api(`/api/event-delivery-notes/${id}/client-sign`,{method:'POST',body:JSON.stringify(b)}); closeModal(); await loadBase(); renderShell(); toast('Albarán firmado y bloqueado')}catch(err){toast(err.message)}}; }
documentacion = function(){ $('#main').innerHTML=header('Documentación PRL','Subida real de documentos, caducidades y estado documental.','<button class="blue" onclick="docUploadModal()">Subir documento</button>')+`<section class="card">${table(['Título','Tipo','Propietario','Caducidad','Archivo','Notas'],state.documents.map(d=>[esc(d.title),esc(d.type),esc(d.owner_type),esc(d.expiry_date),d.url?`<a href="${esc(d.url)}" target="_blank">Descargar</a>`:'-',esc(d.notes)]))}</section>`; }
window.docUploadModal=()=>{ modal(`<h3>Subir documento</h3><form id="f" class="formgrid"><input name="title" placeholder="Título" required><input name="type" placeholder="Tipo"><input name="owner_type" placeholder="Operario / Cliente / Empresa"><input name="owner_id" placeholder="ID propietario"><input name="expiry_date" type="date"><input name="file" type="file"><textarea name="notes" placeholder="Notas"></textarea><button class="blue">Guardar</button><button type="button" class="secondary" onclick="closeModal()">Cancelar</button></form>`); $('#f').onsubmit=async e=>{e.preventDefault(); const fd=new FormData(e.target); const file=fd.get('file'); const b=Object.fromEntries(fd); delete b.file; if(file&&file.size){ b.original_name=file.name; b.data_url=await new Promise(res=>{const r=new FileReader(); r.onload=()=>res(r.result); r.readAsDataURL(file);}); } try{await api('/api/documents/upload-json',{method:'POST',body:JSON.stringify(b)}); closeModal(); await loadBase(); renderShell(); toast('Documento subido')}catch(err){toast(err.message)}}; }
function auditoria(){ $('#main').innerHTML=header('Auditoría y seguridad','Registro de acciones importantes del sistema.')+`<section class="card">${table(['Fecha','Usuario','Acción','Entidad','ID'],(state.auditLogs||[]).map(l=>[esc(l.created_at),esc(l.user_name||''),esc(l.action),esc(l.entity),esc(l.entity_id)]))}</section>`; }
