// ---------- V2.0.9 PERSISTENCIA + LOGIN SEPARADO + JEFE DE EQUIPO ----------
function loginFormHtml(kind){
  const isAdmin = kind === 'admin';
  return `<form id="loginForm" class="login-form-block"><div class="field"><label>${isAdmin?'Email administrador':'Teléfono o email operario'}</label><input name="login" value="${isAdmin?'admin@marfan.local':''}" placeholder="${isAdmin?'admin@marfan.local':'Ej: 645252250'}" required></div><div class="field"><label>Contraseña</label><input name="password" type="password" value="${isAdmin?'Admin1234!':''}" placeholder="Contraseña" required></div><button class="blue full">Entrar como ${isAdmin?'administrador':'operario'}</button></form>`;
}
renderLogin = function(active='admin'){
  app.innerHTML=`<main class="login"><section class="login-card login-card-wide"><div class="brand big"><img src="/logo.png" onerror="this.style.display='none'"><div><h1>Marfan Crew 2.0.9</h1><p>Base limpia · datos persistentes · login separado</p></div></div><div class="login-tabs"><button class="${active==='admin'?'active':''}" id="tabAdmin">Login administrador</button><button class="${active==='operator'?'active':''}" id="tabOperator">Login operario</button></div><div id="loginBox">${loginFormHtml(active)}</div><p class="muted small login-help"><b>Admin inicial:</b> admin@marfan.local / Admin1234!<br><b>Operarios:</b> teléfono o email + clave asignada desde administración.</p></section></main>`;
  $('#tabAdmin').onclick=()=>renderLogin('admin');
  $('#tabOperator').onclick=()=>renderLogin('operator');
  $('#loginForm').onsubmit=async e=>{e.preventDefault(); try{ const r=await api('/api/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))}); token=r.token; me=r.user; localStorage.setItem('token',token); localStorage.setItem('me',JSON.stringify(me)); state.page = ['operator','client'].includes(me.role) ? 'vista-operario' : 'dashboard'; await boot(); }catch(err){toast(err.message)}};
};
const _visiblePagesV209 = visiblePages;
visiblePages = function(){
  if(['operator','client'].includes(me?.role)) return pages.filter(p=>['vista-operario'].includes(p[1]));
  if(me?.role==='team_lead') return pages.filter(p=>!['usuarios','passwords','ajustes'].includes(p[1]));
  return _visiblePagesV209 ? _visiblePagesV209() : pages;
};
const _renderShellV209 = renderShell;
renderShell = function(){
  const groups={}; visiblePages().forEach(p=>(groups[p[0]]??=[]).push(p));
  app.innerHTML=`<div class="shell"><aside class="side"><div class="brand"><img src="/logo.png" onerror="this.remove()"><div><h1>MARFAN CREW</h1><p>App 2.0.9</p></div></div><div class="nav">${Object.entries(groups).map(([g,items])=>`<div class="navgroup"><span>${g}</span>${items.map(p=>`<button data-page="${p[1]}" class="${state.page===p[1]?'active':''}">${p[2]}</button>`).join('')}</div>`).join('')}</div><div class="userbox"><p>${esc(me?.name||'')}<br><b>${roleLabel(me?.role)}</b></p><button class="secondary full" id="logout">Salir</button></div></aside><main class="main" id="main"></main></div>`;
  document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page; renderShell();});
  $('#logout').onclick=()=>{localStorage.clear();token=null;me=null;renderLogin('admin')}; renderPage();
};
function workerOption(u){ return `<option value="${u.id}" data-rate="${Number(u.hourly_rate||u.default_day_rate||0)}" data-role="${esc(u.operator_role_name||u.position||'')}" data-islead="${u.role==='team_lead'?'1':'0'}">${esc(u.name)} · ${roleLabel(u.role)} · ${esc(u.phone||'')}</option>`; }
function assignmentRow(a={}){
  const workers=(state.users||[]).filter(u=>['operator','team_lead'].includes(u.role));
  const rid='ass_'+Math.random().toString(36).slice(2);
  return `<div class="assignment-row" data-row="1"><select name="user_id" id="${rid}" required><option value="">Seleccionar operario</option>${workers.map(workerOption).join('')}</select><input name="role_label" placeholder="Rol en evento / tarea" value="${esc(a.role_label||'')}"><input name="planned_start" type="time" value="${esc(a.planned_start||'')}"><input name="planned_end" type="time" value="${esc(a.planned_end||'')}"><input name="hourly_rate" type="number" step="0.01" placeholder="€/h" value="${Number(a.hourly_rate||0)}"><label class="check"><input name="is_team_lead" type="checkbox" ${a.is_team_lead?'checked':''}> Jefe de equipo / firma cliente</label><button type="button" class="secondary" onclick="this.closest('.assignment-row').remove()">Quitar</button></div>`;
}
eventModal = async function(id=null, preDate=''){
  const isEdit=!!id; const data=await api(`/api/event-form-data${id?'?id='+id:''}`).catch(()=>({event:null,assignments:[],clients:state.clients,users:state.users,rates:state.rates}));
  const ev=data.event||{}; const assigns=data.assignments||[]; const clients=data.clients||state.clients||[];
  modal(`<h3>${isEdit?'Editar evento completo':'Crear evento completo'}</h3><form id="f" class="formgrid event-form-pro"><input name="title" placeholder="Nombre del evento" value="${esc(ev.title||'')}" required><input name="event_code" placeholder="Código evento" value="${esc(ev.event_code||'')}"><select name="client_id"><option value="">Cliente</option>${clients.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><input name="date" type="date" value="${esc(ev.date||preDate||new Date().toISOString().slice(0,10))}" required><input name="start_time" type="time" value="${esc(ev.start_time||'09:00')}" required><input name="end_time" type="time" value="${esc(ev.end_time||'18:00')}" required><input name="load_in_time" type="time" value="${esc(ev.load_in_time||'')}"><input name="load_out_time" type="time" value="${esc(ev.load_out_time||'')}"><input name="location" placeholder="Lugar" value="${esc(ev.location||'')}"><input name="address" placeholder="Dirección" value="${esc(ev.address||'')}"><input name="google_maps_link" placeholder="Google Maps" value="${esc(ev.google_maps_link||'')}"><input name="service_type" placeholder="Tipo de servicio" value="${esc(ev.service_type||'')}"><select name="status"><option value="planned">Planificado</option><option value="confirmed">Confirmado</option><option value="done">Realizado</option><option value="cancelled">Cancelado</option></select><input name="budget" type="number" step="0.01" placeholder="Presupuesto" value="${Number(ev.budget||0)}"><input name="external_cost" type="number" step="0.01" placeholder="Coste externo" value="${Number(ev.external_cost||0)}"><input name="transport_cost" type="number" step="0.01" placeholder="Transporte" value="${Number(ev.transport_cost||0)}"><input name="other_cost" type="number" step="0.01" placeholder="Otros costes" value="${Number(ev.other_cost||0)}"><textarea name="access_notes" placeholder="Notas de acceso">${esc(ev.access_notes||'')}</textarea><textarea name="parking_notes" placeholder="Parking / descarga">${esc(ev.parking_notes||'')}</textarea><textarea name="material_notes" placeholder="Material">${esc(ev.material_notes||'')}</textarea><textarea name="crew_notes" placeholder="Notas personal">${esc(ev.crew_notes||'')}</textarea><textarea name="production_notes" placeholder="Producción">${esc(ev.production_notes||'')}</textarea><textarea name="notes" placeholder="Notas internas">${esc(ev.notes||'')}</textarea><div class="fullrow card inner"><h4>Equipo asignado</h4><p class="muted">Marca <b>Jefe de equipo / firma cliente</b> en la persona responsable. Ese será quien cierre el trabajo y reciba la firma del cliente.</p><div id="assignmentRows">${assigns.length?assigns.map(assignmentRow).join(''):assignmentRow()}</div><button type="button" class="secondary" id="addAssignment">Añadir operario</button></div><button class="blue">Guardar evento</button><button type="button" class="secondary" onclick="closeModal()">Cancelar</button></form>`);
  if(ev.client_id) $('#f').elements.client_id.value=ev.client_id; if(ev.status) $('#f').elements.status.value=ev.status;
  assigns.forEach((a,i)=>{ const rows=[...document.querySelectorAll('.assignment-row')]; if(rows[i]) rows[i].querySelector('[name=user_id]').value=a.user_id; });
  $('#addAssignment').onclick=()=>$('#assignmentRows').insertAdjacentHTML('beforeend', assignmentRow());
  $('#f').onsubmit=async e=>{ e.preventDefault(); const fd=new FormData(e.target); const body=Object.fromEntries(fd); ['budget','external_cost','transport_cost','other_cost'].forEach(k=>body[k]=Number(body[k]||0)); body.assignments=[...document.querySelectorAll('.assignment-row')].map(row=>({ user_id:Number(row.querySelector('[name=user_id]').value||0), role_label:row.querySelector('[name=role_label]').value||'', planned_start:row.querySelector('[name=planned_start]').value||body.start_time, planned_end:row.querySelector('[name=planned_end]').value||body.end_time, hourly_rate:Number(row.querySelector('[name=hourly_rate]').value||0), is_team_lead:row.querySelector('[name=is_team_lead]').checked?1:0, status:'asignado' })).filter(a=>a.user_id); try{ await api('/api/event-form-save',{method:'POST',body:JSON.stringify({...body,id:id||0})}); closeModal(); await loadBase(); state.calendar = state.calendar || {}; state.calendar.date=new Date((body.date||new Date().toISOString().slice(0,10))+'T00:00:00'); renderShell(); toast('Evento guardado con equipo asignado'); }catch(err){toast(err.message)} };
};
operarios = function(){
  const workers=(state.users||[]).filter(u=>['operator','team_lead'].includes(u.role));
  $('#main').innerHTML=header('Operarios','Desde aquí puedes convertir cualquier operario en Jefe de Equipo. El jefe de equipo será el responsable de firma del cliente al terminar el trabajo.', '<button class="blue" onclick="userModal({role:\'operator\',password:\'Marfan1234*\'})">Crear operario</button><button class="secondary" onclick="userModal({role:\'team_lead\',password:\'Marfan1234*\'})">Crear jefe equipo</button>')+`<section class="card"><p class="muted"><b>Persistencia activada:</b> los datos se guardan en la base persistente y no se machacan al actualizar.</p>${table(['Nombre','Rol','Teléfono','DNI','Cargo','Tarifa','Firma cliente','Activo','Acciones'],workers.map(u=>[esc(u.name),roleLabel(u.role),esc(u.phone),esc(u.dni),esc(u.operator_role_name||u.position),money(u.hourly_rate||u.default_day_rate),u.role==='team_lead'?'<span class="pill">Puede recibir firma</span>':'-',u.active?'Sí':'No',`<button class="blue smallbtn" onclick="operatorFolder(${u.id})">Carpeta</button> <button class="secondary smallbtn" onclick="operatorEdit(${u.id})">Editar</button> <button class="secondary smallbtn" onclick="makeTeamLead(${u.id})">Hacer jefe</button> <button class="secondary smallbtn" onclick="makeOperator(${u.id})">Hacer operario</button>`]))}</section>`;
};
window.makeTeamLead=async(id)=>{ const u=(state.users||[]).find(x=>Number(x.id)===Number(id)); if(!u)return; await api(`/api/users/${id}`,{method:'PUT',body:JSON.stringify({...u,role:'team_lead',active:u.active?1:0})}); await loadBase(); renderShell(); toast('Marcado como jefe de equipo'); };
window.makeOperator=async(id)=>{ const u=(state.users||[]).find(x=>Number(x.id)===Number(id)); if(!u)return; await api(`/api/users/${id}`,{method:'PUT',body:JSON.stringify({...u,role:'operator',active:u.active?1:0})}); await loadBase(); renderShell(); toast('Marcado como operario'); };
albaranes = function(){ $('#main').innerHTML=header('Albaranes A4 Pro','El albarán se asocia al jefe de equipo del evento. El cliente puede firmar desde enlace público o desde admin.','<button class="blue" onclick="deliveryModal()">Generar albarán</button>')+`<section class="card">${table(['Número','Fecha','Cliente','Jefe equipo','Horas normales','Horas nocturnas','Total IVA','Estado','Acciones'],(state.notes||[]).map(n=>[esc(n.number),dateES(n.event_date),esc(n.client_name),esc(n.team_lead_name||'-'),Number(n.normal_hours||0).toFixed(2),Number(n.night_hours||0).toFixed(2),money(n.grand_total_vat),n.locked?'Firmado/bloqueado':'Pendiente',`<button class="blue smallbtn" onclick="downloadDeliveryPDF(${n.id})">PDF A4</button> <button class="secondary smallbtn" onclick="createPublicToken(${n.id})">Link firma</button> ${n.locked?'':`<button class="secondary smallbtn" onclick="signDelivery(${n.id})">Firmar</button>`}`]))}</section>`; };
const _dashboardV209 = dashboard;
dashboard = function(){ _dashboardV209(); api('/api/db-status').then(d=>{ const main=$('#main'); if(main) main.insertAdjacentHTML('beforeend', `<section class="card"><h3>Persistencia de datos</h3><p class="muted">Base de datos: <b>${esc(d.persistent?'PERSISTENTE':'LOCAL')}</b> · ${esc(d.db_path)} · ${(d.size_bytes/1024).toFixed(1)} KB</p></section>`); }).catch(()=>{}); };

boot();
